A.ad5=new B.M(A.a2,u.G,A.aB,90,null,null,null,80,90,null,null,null,A.J,A.ay,A.d5,null,null,A.hc,A.iS,A.bhx,A.abS,null,null,null,null,null,A.L,null,null,A.b8I,null,"80-90 mg/kg/day divided q12h (45 mg/kg/dose) for Acute Otitis Media or resistant S. pneumoniae","\u0e02\u0e19\u0e32\u0e14\u0e22\u0e32\u0e2a\u0e39\u0e07 80\u201390 mg/kg/\u0e27\u0e31\u0e19 \u0e41\u0e1a\u0e48\u0e07\u0e43\u0e2b\u0e49\u0e17\u0e38\u0e01 12 \u0e0a\u0e21. (45 mg/kg/\u0e04\u0e23\u0e31\u0e49\u0e07) \u0e2a\u0e33\u0e2b\u0e23\u0e31\u0e1a\u0e2b\u0e39\u0e0a\u0e31\u0e49\u0e19\u0e01\u0e25\u0e32\u0e07\u0e2d\u0e31\u0e01\u0e40\u0e2a\u0e1a\u0e40\u0e09\u0e35\u0e22\u0e1a\u0e1e\u0e25\u0e31\u0e19 (AOM) \u0e2b\u0e23\u0e37\u0e2d\u0e1b\u0e2d\u0e14\u0e2d\u0e31\u0e01\u0e40\u0e2a\u0e1a",A.K,A.cu,null,null,null)
